/** Pre-computed isochore bins with colors, ready for ChromosomeSVG */
export const KARYOTYPE_ISOCHORES: Record<string, IsochoreBin[]> = Object.fromEntries(
  Object.entries(RAW).map(([chr, bins]) => [
    chr,
    bins.map(b => ({ ...b, color: COLOR.isochore[b.isoClass] })),
  ]),
);
